'use client';
import { MapPin, Navigation, Phone, CheckCircle } from 'lucide-react';

export default function OrdersPage() {
    const orders = [
        {
            id: '#ORD-2024-001',
            restaurant: 'Biryani Palace',
            customer: 'Rahul Kumar',
            address: 'Near Old Bus Stand, Degloor',
            amount: '₹450',
            status: 'Delivered',
            time: 'Today, 2:30 PM',
            earnings: '₹45',
        },
        {
            id: '#ORD-2024-002',
            restaurant: 'Spicy Treats',
            customer: 'Amit Singh',
            address: 'Shivaji Chowk, Degloor',
            amount: '₹220',
            status: 'Delivered',
            time: 'Today, 1:15 PM',
            earnings: '₹30',
        },
    ];

    return (
        <div className="p-4 space-y-4">
            <h1 className="text-2xl font-bold text-gray-900">Order History</h1>

            <div className="space-y-4">
                {orders.map((order) => (
                    <div key={order.id} className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm">
                        <div className="flex justify-between items-start mb-3">
                            <div>
                                <h3 className="font-bold text-gray-900">{order.restaurant}</h3>
                                <p className="text-xs text-gray-500">{order.time}</p>
                            </div>
                            <span className="bg-green-100 text-green-700 px-2 py-1 rounded text-xs font-bold">
                                {order.earnings}
                            </span>
                        </div>

                        <div className="space-y-2 mb-4">
                            <div className="flex gap-2">
                                <div className="flex flex-col items-center">
                                    <div className="w-2 h-2 bg-gray-300 rounded-full" />
                                    <div className="w-0.5 h-6 bg-gray-200" />
                                    <div className="w-2 h-2 bg-primary rounded-full" />
                                </div>
                                <div className="flex-1 space-y-4 pt-1">
                                    <p className="text-xs text-gray-500">Pickup form Restaurant</p>
                                    <div>
                                        <p className="text-sm font-medium text-gray-900">{order.customer}</p>
                                        <p className="text-xs text-gray-500 truncate">{order.address}</p>
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div className="flex items-center justify-between border-t border-gray-100 pt-3">
                            <span className="text-xs font-medium text-gray-600 bg-gray-100 px-2 py-1 rounded-full">{order.id}</span>
                            <div className="flex items-center gap-1 text-green-600 text-xs font-bold">
                                <CheckCircle size={14} />
                                {order.status}
                            </div>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
}
